// Creating a character device node requiring Major/Minor numbers
// Requires CAP_MKNOD capability

dev_t major = 10;
dev_t minor = 2;
dev_t my_dev = makedev(major, minor);

// S_IFCHR (Character device) combined with permissions (0600)
mode_t char_mode = S_IFCHR | 0600;

// mknod(pathname, mode, dev)
int status = mknod("/dev/my_device", char_mode, my_dev);

// -----------------------------------------------------------------

// Creating a Named Pipe (FIFO) using mknodat
// Dev argument is ignored for FIFOs (set to 0)

mode_t pipe_mode = S_IFIFO | 0666;

// AT_FDCWD references the current working directory
int status_at = mknodat(AT_FDCWD, "local_pipe_name", pipe_mode, 0);

